//<![CDATA[
var lst = 0, $arr;
$(document).ready(function() {
	$arr = $('.project_lst_wrap [class*="arr_"]');

	$arr.mouseover(function() {
		$(this).css({opacity:1});
	}).mouseleave(function() {
		$(this).css({opacity:0.5});
	});

	$(document).on('mouseover', '.project_lst2 li a', function() {
		$('.img', this).css({width:'105%', 'max-width':'105%', top:'-2.5%', left:'-2.5%'});
	}).on('mouseleave', '.project_lst2 li a', function() {
		$('.img', this).css({width:'100%', 'max-width':'100%', top:'0', left:'0'});
	});

	$('#div_ajax img.lazy').each(function() {
		$(this).css ( { display:"block" , opacity:0 } ).delay ( Math.random()*700 ).animate ( { opacity:1 } , 600 );
	});


	$('.tab2 li a').click(function() {
		var id = $(this).attr('data-id');

		$('.tab2 li a').removeClass('aon');
		$('.tab2 li a[data-id="'+id+'"]').addClass('aon');

		if (id == 'filter' || id == 'search') {
			if (id == 'filter') $('#search_div').hide();
			else $('#filter_div').hide();

			if ($('.tab2_div').is(':hidden')) $('.tab2_div').slideDown('fast');

			$('#'+id+'_div').fadeIn('fast');
		} else {
			$('.tab2_div').slideUp('fast');
			ajax("", "", "", "", "", "");
		}
	});
});

$(window).load(function() {
	if ($arr.length > 0) project_arr();
});

$(window).scroll(function() {
	if ($arr.length > 0) project_arr();
});

function project_arr() {
	var wt = $(window).scrollTop(), wh = $(window).height()
		, arr_t = $arr.offset().top
		, st = wt + (wh / 2) - ($arr.height() / 2)
		, pr_t = $('.project_lst_wrap').offset().top
		, pr_h = $('.project_lst_wrap').height();

	// 처음에 스크롤 위치 체크
	if (st > pr_t + pr_h - 300) {
		$('.project_lst_wrap').find('[data-id="arr"]').css('top', pr_h - 300);
	}

	// 스크롤 내릴 때
	if (wt > lst) {
		// 현재 화면 중앙의 스크롤 위치가 화살표의 위치를 넘는 경우
		if (st > arr_t && st < pr_t + pr_h - 300) {
			$('.project_lst_wrap').find('[data-id="arr"]').css('top', st - pr_t);
		}
	}
	// 스크롤 올릴 때
	else {
		// 현재 화면 중앙의 스크롤 위치가 화살표의 위치를 넘지 않는 경우
		if (st < arr_t && st > pr_t + 300 - ($arr.height() / 2)) {
			$('.project_lst_wrap').find('[data-id="arr"]').css('top', st - pr_t);
		}
	}

	lst = wt;
}
//]]>

//<![CDATA[
var st, $tab_outer, $tab, $tab2; // 탭메뉴 관련
$(document).ready(function() {
	st = $(window).scrollTop();

	$tab_outer = $('#menu-snb-outer');
	$tab = $('#menu-snb-tab');
	$tab2 = $('.tab2'); // 탭메뉴 관련

	$tab.addClass('after');

	var myt;
	var _resize = function() {
		clearTimeout(myt);
		myt = setTimeout(function() {
			// 탭메뉴
			//if ($tab.length > 0) tabScroll();
			if ($tab.length > 0) {
				$tab_outer.css({height:$tab.height(), 'margin-top':0});
			}
			if ($tab2.length > 0) tabScroll2();

			$('body').css('padding-top', $('.header_wrap').height());				
		}, 300);
	}
	//_resize();

	$(window).on({
		resize: function() {
			//_resize();
		}
		, scroll: function() {
			st = $(this).scrollTop();

			// 탭메뉴
			//if ($tab.length > 0) tabScroll();
			if ($tab2.length > 0) tabScroll2();
		}
	});
});

// 스크롤시 탭 컨트롤
function tabScroll() {
	var hh = $('.header_wrap').outerHeight();
	var tab_st = Math.floor($('.tab_wrap').offset().top);

	if (st >= tab_st - hh) {
		if (!$tab.hasClass('scrolled')) {
			$tab.addClass('scrolled');
			// 탭메뉴의 높이 넣음으로 내용영역 변화 방지
			$('.tab_wrap').height($tab.height());
		}
	} else {
		if ($tab.hasClass('scrolled')) {
			$tab.removeClass('scrolled');
			$('.tab_wrap').height('auto');
		}
	}
}

function tabScroll2() {
	var hh = $('.header_wrap').outerHeight();
	var tab_st = Math.floor($('.tab2_wrap').offset().top);

	if ($tab.length > 0) hh = hh + $tab.height();

	if (st >= tab_st - hh) {
		if (!$tab2.hasClass('scrolled') || !$tab2.hasClass('scrolled2')) {
			// 탭메뉴의 높이 넣음으로 내용영역 변화 방지
			if (!$('.tab2_div').is(':hidden')) $('.tab2_wrap').height($tab2.height() + $('.tab2_div').outerHeight());
			else $('.tab2_wrap').height($tab2.height());

			if ($tab.length > 0) $tab2.addClass('scrolled2');
			else $tab2.addClass('scrolled');
		}
	} else {
		if ($tab2.hasClass('scrolled') || $tab2.hasClass('scrolled2')) {
			$('.tab2_wrap').height('auto');

			if ($tab.length > 0) $tab2.removeClass('scrolled2');
			else $tab2.removeClass('scrolled');
		}
	}
}
